exercises.starter_code:
#include <stdio.h>

int main(void) {
    /* Match expected stdout (trimmed). */
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <string.h>

int main(void) {
    const char *s = "hi";
    fwrite(s, 1, strlen(s), stdout);
    return 0;
}

